      }·
      Linking.openURL(url).catch(() => undefined);
    },
    [navigation],
  );·
  if (!normalizedText) return null;·
  return (
    <View>
      <Text
        className=\"text-body-primary\"
        numberOfLines={
          canCollapse && !isExpanded ? COLLAPSED_CAPTION_LINES : undefined
