      return { label: copy.friendsPrivacyLabel, Icon: Users };
    case 'followers':
      return { label: copy.followersPrivacyLabel, Icon: Users };
    case 'only_me':
      return { label: copy.onlyMePrivacyLabel, Icon: Lock };
    case 'public':
    default:
      return { label: copy.publicLabel, Icon: Globe };
  }
