    collapsible && (textSuggestsOverflow || layoutCanCollapse);·
  useEffect(() => {
    setIsExpanded(false);
    setLayoutCanCollapse(false);
  }, [normalizedText, collapsible]);·
  const handleTextLayout = useCallback(
    (event: any) => {
