    gestureX,
    gestureY,
    gestureActive,
    hasDragged,
    onPick,
    onDismiss,
  }: {
    type: ReactionType;
    label: string;
    index: number;
    pickerLeft: number;
    pickerTop: number;
    iconStartX: number;
    iconSlot: number;
    iconBoxSize: number;
    iconImageSize: number;
    iconCenterOffsetY: number;
    gestureX: any;
    gestureY: any;
    gestureActive: any;
    hasDragged: any;
    onPick: (reaction: ReactionType) => void;
    onDismiss: () => void;
