      const scale = interpolate(
        dist,
        [0, 40, 60],
        [1.5, 1.1, 1],
        Extrapolation.CLAMP,
      );
      const translateY = interpolate(
        dist,
        [0, 40, 60],
        [-15, -5, 0],
        Extrapolation.CLAMP,
      );·
      return {
        transform: [
          { scale: withSpring(scale, { damping: 15 }) },
          { translateY: withSpring(translateY, { damping: 15 }) },
        ],
      };
    });·
